// Some portions generated by Co-Pilot
import { Link } from "@/i18n/navigation";
import { FiArrowRight, FiArrowUpRight } from "react-icons/fi";
import "./styles.css";

interface CommonCardData {
  title: string;
  description: string;
  href: string;
  button: string;
}

interface CommonCardProps {
  data: CommonCardData;
  variant?: "default" | "modern";
}

const CommonCard: React.FC<CommonCardProps> = ({
  data,
  variant = "default",
}) => {
  if (variant === "modern") {
    const Arrow = /^https?:\/\//.test(data.href) ? FiArrowUpRight : FiArrowRight;
    return (
      <article
        data-testid="common-card"
        className="flex min-w-0 flex-col rounded-2xl border border-white/10 bg-white/[0.025] p-6"
      >
        <h3 className="mb-3 text-xl font-semibold leading-snug tracking-tight text-white">
          {data.title}
        </h3>
        <p className="mb-6 text-sm leading-relaxed text-grey">
          {data.description}
        </p>
        <Link
          href={data.href}
          className="mt-auto inline-flex min-h-11 items-center justify-between gap-4 border-t border-white/10 pt-4 text-sm font-medium text-white transition-colors hover:text-[#ff91b7] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
        >
          <span>{data.button}</span>
          <Arrow
            className="shrink-0 text-[#ff91b7]"
            aria-hidden="true"
          />
        </Link>
      </article>
    );
  }
  return (
    <div
      data-testid="common-card"
      className="p-10 flex flex-col max-w-[400px] common-card h-[440px] md:h-[480px] bg-[#200E46]"
    >
      <div className="grow">
        <h3 className="text-white text-[30px] font-semibold whitespace-nowrap md:whitespace-normal leading-[120%] md:text-[40px]">
          {data.title}
        </h3>
        <p className="mt-6 text-xl text-grey font-normal">{data.description}</p>
      </div>
      <Link href={data.href}>
        <button className="bg-transparent border-2 border-pink-500/0 text-white text-base leading-6 font-normal w-[180px] h-[48px] rounded-[80px] gradient-border">
          {data.button}
        </button>
      </Link>
    </div>
  );
};

export default CommonCard;
